(11469,0,0,'%s变得愤怒了！',16,0,100,0,0,0,24144,0,'Eldreth Seether'),
(11486,0,0,'谁敢破坏埃雷萨拉斯的圣洁？懦夫，面对我！',14,0,100,0,0,0,9407,0,'Prince Tortheldrin'),
