(11793,0,1,'你不属于这里！你的身体将成为我造物的养料！',12,0,100,0,0,0,8640,0,'Celebrian Dryad'),
(11794,0,0,'你不属于这些花园。你的身体将滋养我们可爱的造物！',12,0,100,0,0,0,8639,0,'Sister of Celebrian'),
