(16028,1,0,'不玩了？',14,0,100,0,0,8912,28241,0,'patchwerk SAY_SLAY'),
(16028,2,0,'怎么……搞的……',14,0,100,0,0,8911,13070,0,'patchwerk SAY_DEATH'),
