(16064,1,0,'哦……又要血流成河了！',14,0,100,0,0,8903,13038,0,'korthazz SAY_KORT_TAUNT1'),
(16064,1,1,'哦……又要血流成河了！',14,0,100,0,0,8904,0,0,'korthazz SAY_KORT_TAUNT2'),
(16064,1,2,'我要好好享受一下把你们这群傻瓜蛋杀光的感觉！',14,0,100,0,0,8905,13040,0,'korthazz SAY_KORT_TAUNT3'),
(16064,2,0,'我最喜欢烤肉了！',14,0,100,0,0,8902,13037,0,'korthazz SAY_KORT_SPECIAl'),
(16064,3,0,'下次，劳驾多带点朋友来！',14,0,30,0,0,8901,13036,0,'korthazz SAY_KORT_SLAY'),
(16064,4,0,'哦……又要血流成河了！',14,0,100,0,0,8900,13035,0,'korthazz SAY_KORT_DEATH'),
