(16521,0,2,'真可惜，你在坠毁中生还，却要死在这里。',12,0,100,0,0,0,13427,0,'Blood Elf Scout'),
(16521,0,3,'你们谁也休想活着离开这山谷。',12,0,100,0,0,0,13429,0,'Blood Elf Scout'),
(16522,0,0,'你别想抓活的，渣滓！',12,0,100,0,0,0,12767,0,'Surveyor Candress'),
(16523,0,0,'%s变得愤怒了！',16,0,100,0,0,0,24144,0,'Shattered Hand Savage'),
(16523,1,0,'为了卡加斯！为了胜利！',12,0,100,0,0,0,16698,0,'Shattered Hand Savage'),
(16523,1,1,'加卡拉马！',12,0,100,0,0,0,16699,0,'Shattered Hand Savage'),
(16523,1,2,'洛克纳拉什！',12,0,100,0,0,0,16703,0,'Shattered Hand Savage'),
(16523,1,3,'洛克塔·伊拉达里！',12,0,100,0,0,0,16701,0,'Shattered Hand Savage'),
(16523,1,4,'鲜血就是我们的力量！',12,0,100,0,0,0,16700,0,'Shattered Hand Savage'),
