(16523,1,6,'我们是真正的部落！',12,0,100,0,0,0,16697,0,'Shattered Hand Savage'),
(16524,0,0,'求求你们，不要这样！我的儿子……已经疯了！',14,0,100,0,0,9241,13529,0,'aran SAY_AGGRO1'),
(16524,0,1,'我不会再次受辱的！',14,0,100,0,0,9323,15353,0,'aran SAY_AGGRO2'),
(16524,0,2,'你们是谁？你们想要什么？离我远点！',14,0,100,0,0,9324,13530,0,'aran SAY_AGGRO3'),
(16524,1,0,'我要让你们知道，老狗也有几颗牙！',14,0,100,0,0,9245,13519,0,'aran SAY_FLAMEWREATH1'),
(16524,1,1,'燃烧吧，地狱的恶魔！',14,0,100,0,0,9326,13520,0,'aran SAY_FLAMEWREATH2'),
(16524,2,0,'我要把你们全都冰冻！',14,0,100,0,0,9246,13522,0,'aran SAY_BLIZZARD1'),
(16524,2,1,'滚回寒冷的黑暗中去吧！',14,7,100,0,0,9327,22914,0,'aran SAY_BLIZZARD2'),
(16524,3,0,'没错，我的儿子非常强大……但我也有自己的力量！',14,0,100,0,0,9242,13517,0,'aran SAY_EXPLOSION1'),
(16524,3,1,'我不是某个可笑的小丑，我是聂拉斯·埃兰！',14,0,100,0,0,9325,13518,0,'aran SAY_EXPLOSION2'),
(16524,4,0,'你们应该不会不让一个可怜的老人喝点东西吧？不，不，当然不会。',14,0,100,0,0,9248,13514,0,'aran SAY_DRINK'),
(16524,5,0,'还没完！我还有几招没有用呢……',12,0,100,0,0,9251,13513,0,'aran SAY_ELEMENTALS'),
(16524,6,0,'我要结束这场噩梦！',14,0,100,0,0,9250,13526,0,'aran SAY_KILL1'),
(16524,6,1,'不要再烦我了！',14,0,100,0,0,9328,13527,0,'aran SAY_KILL2'),
(16524,7,0,'你们浪费了我太多的时间……让这场游戏结束吧！',14,0,100,0,0,9247,13569,0,'aran SAY_TIMEOVER'),
(16524,8,0,'终于……噩梦结束了……',14,0,100,0,0,9244,15345,0,'aran SAY_DEATH'),
(16524,9,0,'你怎么拿到这个的？是不是他派你来的？',14,0,100,0,0,9249,13532,0,'aran SAY_ATIESH'),
(16524,10,0,'%s 开始把法力注入一个强大的奥术法术。',16,0,100,0,0,0,13515,3,'Shade of Aran EMOTE_ARCANE_EXPLOSION'),
(16534,0,0,'%s感激地点了点头。',16,0,100,2,0,0,12514,0,'Inoculated Nestlewood Owlkin'),
(16534,0,1,'%s困惑不已。',16,0,100,6,0,0,12517,0,'Inoculated Nestlewood Owlkin'),
(16534,0,2,'%s对刚才发生的事感到不快。',16,0,100,18,0,0,12521,0,'Inoculated Nestlewood Owlkin'),
(16534,0,3,'%s有些兴奋过头了。',16,0,100,4,0,0,12516,0,'Inoculated Nestlewood Owlkin'),
(16534,0,4,'%s似乎对疫苗水晶毫不在意。',16,0,100,22,0,0,12520,0,'Inoculated Nestlewood Owlkin'),
(16540,0,0,'不！我们先来的！',12,0,100,0,0,0,13960,0,'Shadow Pillager - On Aggro'),
(16540,0,1,'图书馆的秘密是我们的！',12,0,100,0,0,0,13961,0,'Shadow Pillager - On Aggro'),
(16540,0,2,'这地方的秘密不是给你这样的人的！',12,0,100,0,0,0,0,0,'Shadow Pillager - On Aggro'),
(16540,1,0,'回去吧！',12,0,100,0,0,0,13965,0,'Shadow Pillager - On Kill'),
(16540,1,1,'菜鸟！你已经快步入深渊了！',12,0,100,0,0,0,13968,0,'Shadow Pillager - On Kill'),
(16540,1,2,'这座塔可不适合菜鸟！',12,0,100,0,0,0,13969,0,'Shadow Pillager - On Kill'),
