(16540,2,1,'你们唯一的结局就是陷入永恒的诅咒！',12,0,100,0,0,0,13972,0,'Shadow Pillager - On Death'),
(16544,0,0,'回头吧，在你还有机会回头的时候……',12,0,100,0,0,0,13965,0,'Ethereal Thief'),
(16544,0,1,'图书馆的秘密是我们的，是我们自己的！',12,0,100,0,0,0,13961,0,'Ethereal Thief - On Aggro'),
(16544,0,2,'这个地方的秘密不是你这种人可以接触的！',12,0,100,0,0,0,0,0,'Ethereal Thief - On Aggro'),
(16544,1,0,'你们唯一的结局就是陷入永恒的诅咒！',12,0,100,0,0,0,13972,0,'Ethereal Thief'),
(16544,1,1,'门外汉！你太自不量力了！',12,0,100,0,0,0,13968,0,'Ethereal Thief - On Kill'),
(16544,1,2,'不是我们的成员，就休想踏足这座塔！',12,0,100,0,0,0,13969,0,'Ethereal Thief - On Kill'),
