(18180,1,0,'小心，菲兹，他们冲我们来了！',12,0,100,0,0,0,15089,0,'Hemet Nesingwary'),
(18185,0,0,'%s 大声嘶叫，准备攻击。',16,0,100,0,0,0,14853,0,'Feralfen Serpent Spirit'),
(18200,0,0,'%s 微笑并收起步枪。',16,0,100,0,0,0,15091,0,'Shado \'Fitz\' Farstrider'),
(18202,0,0,'想跑？没门！消灭他们！',12,0,100,0,0,0,15003,0,'maghar captive SAY_MAG_MORE_REPLY'),
(18206,0,0,'何时才能结束这种痛苦啊？',12,0,100,0,0,0,15108,0,'Wastewalker Captive'),
(18206,0,1,'救救我！请救救我！',12,0,100,0,0,0,15103,0,'Wastewalker Captive'),
(18206,0,2,'你怎么能就这么把我留在这里？',12,0,100,0,0,0,15106,0,'Wastewalker Captive'),
