(18218,3,0,'赫米特？菲兹？',12,0,100,0,0,0,15094,0,'Harold Lane'),
(18218,4,0,'太好了，我开始担心了。',12,0,100,0,0,0,15095,0,'Harold Lane'),
(18218,5,0,'%s 动了动，因刺伤而呻吟。',16,0,100,0,0,0,15157,0,'Harold Lane'),
