(18292,0,2,'他怎么做到的？',12,1,100,6,0,0,16231,0,''),
(18293,0,0,'他真是训练有素！',12,1,100,5,0,0,16236,0,''),
(18293,0,1,'他真是纪律严明！',12,1,100,21,0,0,16237,0,''),
(18293,0,2,'他是怎么做到的？',12,1,100,6,0,0,16238,0,''),
(18294,0,0,'嗨，哈罗德。我把你的皮带来了！',12,0,100,3,0,0,15102,0,'Kristen Dipswitch'),
(18294,1,0,'呃！谁来帮帮我！',12,0,100,0,0,0,15104,0,'Kristen Dipswitch'),
