(19181,0,0,'卫兵！',14,7,100,0,0,0,4566,0,'Lemla Hopewing'),
(19188,0,0,'%s变得愤怒了！',16,0,100,0,0,0,24144,0,'Raging Colossus'),
(19191,0,0,'多傲慢啊！多自大啊！你觉得你可以在我的门口打败我吗？',14,0,100,0,0,0,17653,0,'Arazzius the Cruel'),
(19191,1,0,'主人，我失败了……',14,0,100,0,0,0,16429,0,'Arazzius the Cruel'),
(19191,2,0,'蠢货！你是个在不属于你理解的世界里玩耍的孩子。别再说了！',14,0,100,0,0,0,16858,0,'Arazzius the Cruel'),
