(19220,1,0,'我正在寻找一个伙伴……',14,0,100,0,0,11197,18716,0,'pathaleon SAY_DOMINATION_1'),
(19220,1,1,'你现在为我干活！',14,0,100,0,0,11198,20040,0,'pathaleon SAY_DOMINATION_2'),
(19220,2,0,'是叫人帮忙的时候了。',14,0,100,0,0,11196,18717,0,'pathaleon SAY_SUMMON'),
(19220,3,0,'我喜欢自己动手……',14,0,100,0,0,11199,18725,0,'pathaleon SAY_ENRAGE'),
(19220,4,0,'一点小麻烦。',14,0,100,0,0,11194,20042,0,'pathaleon SAY_SLAY_1'),
(19220,4,1,'你好像输了。',14,0,100,0,0,11195,20043,0,'pathaleon SAY_SLAY_2'),
