(20885,2,1,'你选错了对手。',14,0,100,0,0,11088,19981,0,'Dalliah the Doomsayer - Kill'),
(20885,3,0,'旋风斩！',14,0,100,0,0,11089,19982,0,'Dalliah the Doomsayer - Cast Whirlwind'),
(20885,3,1,'我要把你们削成碎片！',14,0,100,0,0,11090,19983,0,'Dalliah the Doomsayer - Cast Whirlwind'),
(20885,4,0,'感觉好多了。',14,0,100,0,0,11091,19984,0,'Dalliah the Doomsayer - Cast Heal'),
