(21044,0,1,'你永远逃不出盘牙……',12,0,100,0,0,0,18693,0,'Coilskar Assassin'),
(21049,0,0,'你诅咒了我们……我们完蛋了。',12,0,100,20,0,0,18700,0,'Spirit of the Past'),
(21049,0,1,'住手！你必须马上住手！',12,0,100,20,0,0,18698,0,'Spirit of the Past'),
(21049,0,2,'不要这么做，古尔丹！元素们永远都不会原谅我们的！',12,0,100,20,0,0,18697,0,'Spirit of the Past'),
(21049,0,3,'想想我们的后代，古尔丹！你会毁灭我们的！',12,0,100,20,0,0,18699,0,'Spirit of the Past'),
(21049,0,4,'如果它们拒绝给予，我们就强夺！',12,0,100,15,0,0,18696,0,'Spirit of the Past'),
