(21661,0,0,'%s变得狂怒无比！',16,0,100,0,0,0,10677,0,'Cabal Skirmisher'),
(21661,1,0,'你的末日到了！',12,0,100,0,0,0,16800,0,'Cabal Skirmisher'),
(21661,1,1,'别想轻易逃跑！',12,0,100,0,0,0,20165,0,'Cabal Skirmisher'),
