(21661,1,4,'以萨格拉斯的名义！',12,0,100,0,0,0,16799,0,'Cabal Skirmisher'),
(21661,1,5,'我必须这么做！',12,0,100,0,0,0,16801,0,'Cabal Skirmisher'),
