(23257,0,0,'瞧，是$n，我们的王牌飞行员。',12,0,100,0,0,0,21885,0,'Skyguard Windcharger'),
(23257,0,1,'$n，天空的统帅，你在干什么？',12,0,100,0,0,0,21893,0,'Skyguard Windcharger'),
(23257,0,2,'立正，$n军官来了！',12,0,100,0,0,0,21891,0,'Skyguard Windcharger'),
