(28684,2,0,'我本该感谢你们的……但我已经没有那个资格了……',14,0,100,0,0,14087,32283,0,'krik thir SAY_DEATH'),
(28684,3,0,'它们很饿了……',14,0,100,0,0,14085,32281,0,'krik thir SAY_SWARM_1'),
(28684,3,1,'宠物们，该吃晚饭了！',14,0,100,0,0,14086,32282,0,'krik thir SAY_SWARM_2'),
(28684,4,0,'小心守着隧道。我们不能让任何人通过！',14,0,100,0,0,14082,32278,0,'krik thir SAY_PREFIGHT_1'),
(28684,4,1,'我听到了脚步声。提高警惕。',14,0,100,0,0,14083,32279,0,'krik thir SAY_PREFIGHT_2'),
