(29001,0,0,'十字军会从这个世界上抹去你们的存在！',14,0,100,0,0,0,29215,0,'high inquisitor valroth'),
(29001,1,0,'看样子我得亲自对付你了。尝尝大检查官的厉害吧，天灾军团！',14,0,100,0,0,0,29216,0,'high inquisitor valroth'),
(29001,2,0,'你想要寻求救赎？我就是你的救星！',12,0,100,0,0,0,29222,0,'high inquisitor valroth'),
(29001,2,1,'接受圣光的净化吧！',12,0,100,0,0,0,29221,0,'high inquisitor'),
(29001,2,2,'懦夫！',12,0,100,0,0,0,30699,0,'high inquisitor valroth'),
