(35119,3,0,'%s用正义之锤对准了$n！',41,0,100,0,0,16136,35408,0,'Eadric the Pure - EMOTE_HAMMER_RIGHTEOUS'),
(35119,4,0,'正义之锤！',14,0,100,0,0,16136,35442,0,'Eadric the Pure - SAY_HAMMER_RIGHTEOUS'),
(35119,5,0,'呃！你！回去再练练吧。',14,0,100,0,0,16137,35759,0,'Eadric the Pure - SAY_KILL_PLAYER'),
(35119,5,1,'不！不！我再说一遍，不！还不够好。',14,0,100,0,0,16138,35760,0,'Eadric the Pure - SAY_KILL_PLAYER'),
