(36856,1,1,'干的真不赖！',12,0,14,4,0,0,37988,0,'Shandy say 2'),
(36856,1,2,'阿夸诺斯要忙不过来了！',12,0,14,4,0,0,37987,0,'Shandy say 2'),
(36856,1,3,'干得好。我不想知道那点污迹究竟是什么。',12,0,14,0,0,0,37989,0,'Shandy Glossgleam'),
(36856,1,4,'这才叫干活！',12,0,14,0,0,0,37986,0,'Shandy Glossgleam'),
(36856,1,5,'干净利落！',12,0,14,0,0,0,37985,0,'Shandy Glossgleam'),
(36856,1,6,'不错。我不想知道那污渍是什么。',12,0,14,0,0,0,37987,0,'Shandy Glossgleam'),
(36856,1,7,'阿奎诺斯快跟不上了！',12,0,14,0,0,0,37988,0,'Shandy Glossgleam'),
(36856,2,0,'快点儿，扔几件衬衫到洗衣桶里！',12,0,100,0,0,0,36762,0,'Shandy Glossgleam'),
(36856,3,0,'加几件儿恶心的…呃，我是说，“棘手的”！',12,0,100,25,0,0,36790,0,'Shandy Glossgleam'),
(36856,4,0,'桶里需要加水！',12,0,100,0,0,0,36788,0,'Shandy Glossgleam'),
(36856,5,0,'朝桶里扔几条裤子！',12,0,100,25,0,0,36787,0,'Shandy Glossgleam'),
(36856,6,0,'我应该留住你的。',12,0,100,25,0,0,36789,0,'Shandy Glossgleam'),
